const fields = [
  "request_id",
  "name",
  "contact",
  "service",
  "budget",
  "message",
  "timeline"
];

const intents = new Set(["buy", "interested", "unclear"]);
const urgencies = new Set(["high", "medium", "low"]);

const outputKeys = new Set([
  "lead_score",
  "intent",
  "urgency",
  "reason"
]);

const clip = value =>
  Array.from(value).slice(0, 160).join("");

return $input.all().map((item, index) => {

  // В Worker за один запуск обрабатываем одну AI-заявку.
  const source = $("Build Worker Context").first().json;

  const attempts = Number(source.processing_attempts);

  if (
    !/^\d+$/.test(String(source.id ?? "")) ||
    !/^\d+$/.test(String(source.processing_token ?? "")) ||
    !Number.isInteger(attempts) ||
    attempts < 1
  ) {
    throw new Error("Invalid Worker job context");
  }

  const json = {};

  for (const field of fields) {
    json[field] = source[field] ?? null;
  }

  Object.assign(json, {
    id: source.id,
    processing_token: source.processing_token,
    processing_attempts: attempts
  });

  const output = item.json?.output;
  const error = item.json?.error;

  const isObject =
    output !== null &&
    typeof output === "object" &&
    !Array.isArray(output);

  const reason =
    isObject && typeof output.reason === "string"
      ? output.reason
          .replace(/[\u0000-\u001f\u007f]/g, " ")
          .replace(/\s+/gu, " ")
          .trim()
      : "";

  const valid =
    isObject &&
    !error &&
    Object.keys(output).length === 4 &&
    Object.keys(output).every(key => outputKeys.has(key)) &&
    Number.isInteger(output.lead_score) &&
    output.lead_score >= 0 &&
    output.lead_score <= 100 &&
    intents.has(output.intent) &&
    urgencies.has(output.urgency) &&
    reason.length > 0;

  if (valid) {
    Object.assign(json, {
      action: "success",
      lead_score: output.lead_score,
      intent: output.intent,
      urgency: output.urgency,
      reason: clip(reason),
      ai_reason_truncated: Array.from(reason).length > 160
    });

  } else {
    const errorObject =
      error && typeof error === "object" ? error : {};

    const rawStatus =
      errorObject.statusCode ??
      errorObject.status ??
      errorObject.response?.statusCode ??
      errorObject.response?.status ??
      item.json?.statusCode;

    const status = Number(rawStatus);

    const errorText =
      typeof error === "string"
        ? error
        : typeof errorObject.message === "string"
          ? errorObject.message
          : "";

    const parserError =
      /parser|parsing|output.*format|json schema/i.test(errorText) ||
      errorObject.name === "OutputParserException";

    const permanentError =
      [400, 401, 403, 404, 422].includes(status);

    const shouldReview =
      !error ||
      parserError ||
      permanentError ||
      attempts >= 3;

    const safeError =
      !error
        ? "AI_INVALID_OUTPUT"
        : parserError
          ? "AI_PARSER_ERROR"
          : Number.isInteger(status) && status >= 100
            ? `AI_HTTP_${status}`
            : "AI_TECHNICAL_ERROR";

    const retryAfterRaw =
      errorObject.retry_after ??
      errorObject.retryAfter ??
      errorObject.response?.headers?.["retry-after"];

    const retryAfter =
      retryAfterRaw === null ||
      retryAfterRaw === undefined ||
      retryAfterRaw === ""
        ? 0
        : Number(retryAfterRaw);

    const baseDelay = attempts === 1 ? 120 : 600;

    const delaySeconds = Math.max(
      baseDelay,
      Number.isFinite(retryAfter) && retryAfter > 0 && retryAfter <= 2147483647
        ? Math.ceil(retryAfter)
        : 0
    );

    Object.assign(json, {
      action: shouldReview ? "review" : "retry",
      lead_score: null,
      intent: "unclear",
      urgency: "low",
      safe_error: safeError,
      delay_seconds: shouldReview ? null : delaySeconds
    });
  }

  return {
    json,
    pairedItem: { item: index }
  };
});

return $input.all().map((item, index) => ({
  json: { ...item.json, safe_error: "AI_ATTEMPTS_EXHAUSTED" },
  pairedItem: { item: index }
}));

return $input.all().map((item, index) => {

  const job = item.json.telegram_job;

  if (
    !job ||
    typeof job !== "object" ||
    Array.isArray(job)
  ) {
    throw new Error(
      "Invalid Telegram job received from PostgreSQL"
    );
  }

  return {
    json: {
      ...job
    },
    pairedItem: {
      item: index
    }
  };

});

