if not _items:
    return []


LIMIT = 4096


def escape_html(value):
    if value is None:
        return ""

    return (
        str(value)
        .replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def clip(value, limit):
    if value is None:
        return ""

    return str(value)[:limit]


def utf16_len(value):
    total = 0

    for char in value:
        if ord(char) > 0xFFFF:
            total += 2
        else:
            total += 1

    return total


def escape_with_limit(value, capacity):
    raw = str(value or "")
    escaped = escape_html(raw)

    if utf16_len(escaped) <= capacity:
        return escaped

    suffix = (
        "\n…\n"
        "Полный текст задачи сохранён в базе."
    )

    available = max(
        0,
        capacity - utf16_len(suffix)
    )

    result = []
    current_length = 0

    for char in raw:
        escaped_char = escape_html(char)
        char_length = utf16_len(
            escaped_char
        )

        if (
            current_length
            + char_length
            > available
        ):
            break

        result.append(
            escaped_char
        )

        current_length += (
            char_length
        )

    return (
        "".join(result)
        + suffix
    )


def format_budget(value):
    if value is None:
        return "Нужна оценка стоимости"

    if isinstance(value, bool):
        return "Нужна проверка суммы"

    amount = None

    if isinstance(value, int):
        amount = value

    elif isinstance(value, float):
        if value.is_integer():
            amount = int(value)

    elif isinstance(value, str):
        value = value.strip()

        if value.isdigit():
            amount = int(value)

    if (
        amount is None
        or amount <= 0
        or amount > 1_000_000_000
    ):
        return "Нужна проверка суммы"

    return (
        f"{amount:,}"
        .replace(",", " ")
        + " ₽"
    )


result = []


for index, item in enumerate(_items):

    data = dict(
        item["json"]
    )

    review = (
        data.get("lead_status")
        == "needs_review"
        or data.get(
            "ai_review_required"
        ) is True
    )

    lead_status = data.get(
        "lead_status"
    )

    if review:
        status = (
            "⚠️ Нужна ручная проверка"
        )

    elif lead_status == "hot_lead":
        status = (
            "🔥 Приоритетная заявка"
        )

    elif lead_status == "regular_lead":
        status = (
            "🟢 Новая заявка"
        )

    else:
        status = "Новая заявка"

    # -------------------------
    # AI RESULT
    # -------------------------

    if review:

        score_text = (
            "Не определена — "
            "ручная проверка"
        )

        intent_text = (
            "Не определено — "
            "ручная проверка"
        )

        urgency_text = (
            "Не определена — "
            "ручная проверка"
        )

    else:

        score = data.get(
            "lead_score"
        )

        if (
            isinstance(score, int)
            and not isinstance(score, bool)
            and 0 <= score <= 100
        ):
            score_text = (
                f"{score}/100 "
                "(рекомендация AI)"
            )
        else:
            score_text = (
                "Не определена"
            )

        intent_labels = {
            "buy":
                "Есть намерение заказать",

            "interested":
                "Заинтересован",

            "unclear":
                "Нужны уточнения",
        }

        urgency_labels = {
            "high":
                "Высокая",

            "medium":
                "Средняя",

            "low":
                "Низкая / не указана",
        }

        intent_text = (
            intent_labels.get(
                data.get("intent"),
                "Не определено"
            )
        )

        urgency_text = (
            urgency_labels.get(
                data.get("urgency"),
                "Не определена"
            )
        )

    # -------------------------
    # OTHER FIELDS
    # -------------------------

    budget_text = format_budget(
        data.get("budget")
    )

    timeline = (
        data.get("timeline")
        or "Пока не определены"
    )

    reason = data.get("reason")

    if not reason:
        if review:
            reason = (
                "AI-анализ не выполнен. "
                "Заявка сохранена и "
                "требует ручной проверки."
            )
        else:
            reason = (
                "Комментарий отсутствует."
            )

    name = escape_html(
        clip(
            data.get("name")
            or "Не указано",
            60
        )
    )

    contact = escape_html(
        clip(
            data.get("contact")
            or "Не указан",
            270
        )
    )

    service = escape_html(
        clip(
            data.get("service")
            or "Не указано",
            100
        )
    )

    timeline_text = escape_html(
        clip(
            timeline,
            100
        )
    )

    request_id = escape_html(
        clip(
            data.get("request_id")
            or "Не указан",
            36
        )
    )

    reason_text = escape_html(
        clip(
            reason,
            160
        )
    )

    # -------------------------
    # MESSAGE
    # -------------------------

    header = "\n".join([
        f"<b>{status}</b>",
        "",
        f"Имя: {name}",
        f"Контакт: {contact}",
        f"Направление: {service}",
        f"Бюджет: {escape_html(budget_text)}",
        f"Сроки: {timeline_text}",
        f"ID: {request_id}",
        "",
        "<b>Задача:</b>",
        ""
    ])

    footer = "\n".join([
        "",
        "",
        "<b>Квалификация:</b>",
        f"Оценка: {escape_html(score_text)}",
        f"Намерение: {escape_html(intent_text)}",
        f"Срочность: {escape_html(urgency_text)}",
        "",
        "<b>Комментарий:</b>",
        reason_text
    ])

    task_capacity = max(
        0,
        LIMIT
        - utf16_len(header)
        - utf16_len(footer)
    )

    task = escape_with_limit(
        data.get("message")
        or "Не описана",
        task_capacity
    )

    manager_message = (
        header
        + task
        + footer
    )

    data["manager_message"] = (
        manager_message
    )

    result.append({
        "json": data,
        "pairedItem": {
            "item": index
        }
    })


return result

