const source = $("Build Telegram Context").first().json;

return $input.all().map((item, index) => {

  const response = item.json;

  const messageId =
    response.result?.message_id ??
    response.message_id;

  if (
    response.ok === false ||
    !/^\d+$/.test(String(messageId ?? ""))
  ) {
    throw new Error(
      "Telegram success response has no valid message_id"
    );
  }

  if (
    !/^\d+$/.test(String(source.id ?? "")) ||
    !/^\d+$/.test(String(source.telegram_token ?? ""))
  ) {
    throw new Error("Invalid Telegram job context");
  }

  return {
    json: {
      id: source.id,
      telegram_token: source.telegram_token,
      message_id: String(messageId)
    },
    pairedItem: {
      item: index
    }
  };

});

const source = $("Build Telegram Context").first().json;

const attempts = Number(source.telegram_attempts);

if (
  !/^\d+$/.test(String(source.id ?? "")) ||
  !/^\d+$/.test(String(source.telegram_token ?? "")) ||
  !Number.isInteger(attempts) ||
  attempts < 1
) {
  throw new Error("Invalid Telegram job context");
}

return $input.all().map((item, index) => {

  const error = item.json.error ?? {};

  const details =
    typeof error === "object" && error !== null
      ? error
      : {};

  // 1. Получаем текст ошибки.
  const errorMessage =
    typeof error === "string"
      ? error
      : String(
          details.description ??
          details.message ??
          details.response?.body?.description ??
          ""
        );

  // 2. Ищем HTTP-код в структурированных данных.
  const rawStatus =
    details.statusCode ??
    details.httpCode ??
    details.status ??
    details.cause?.statusCode ??
    details.cause?.httpCode ??
    details.response?.statusCode ??
    details.response?.status ??
    item.json.statusCode ??
    item.json.httpCode;

  const parsedStatus = Number(rawStatus);

  const hasStructuredStatus =
    Number.isInteger(parsedStatus) &&
    parsedStatus >= 100 &&
    parsedStatus <= 599;

  // 3. Если числового кода нет,
  // определяем его по стандартному тексту Telegram.
  let inferredStatus = null;

  if (/^Bad Request(?::|\s|$)/i.test(errorMessage)) {
    inferredStatus = 400;
  } else if (/^Unauthorized(?::|\s|$)/i.test(errorMessage)) {
    inferredStatus = 401;
  } else if (/^Forbidden(?::|\s|$)/i.test(errorMessage)) {
    inferredStatus = 403;
  } else if (/^Too Many Requests(?::|\s|$)/i.test(errorMessage)) {
    inferredStatus = 429;
  }

  const status = hasStructuredStatus
    ? parsedStatus
    : inferredStatus;

  const validStatus =
    Number.isInteger(status) &&
    status >= 100 &&
    status <= 599;

  // 4. Определяем постоянную ошибку.
  const permanent =
    validStatus &&
    [400, 401, 403].includes(status);

  // 5. Задержки после попыток №1–4.
  const delays = [60, 300, 900, 3600];

  const baseDelay = delays[
    Math.min(attempts - 1, delays.length - 1)
  ];

  // 6. Учитываем retry_after, если Telegram его вернул.
  const retryAfterRaw =
    details.retry_after ??
    details.retryAfter ??
    details.parameters?.retry_after ??
    details.response?.body?.parameters?.retry_after;

  const retryAfter = Number(retryAfterRaw);

  const delaySeconds = Math.max(
    baseDelay,
    Number.isInteger(retryAfter) &&
    retryAfter > 0 &&
    retryAfter <= 2147483647
      ? retryAfter
      : 0
  );

  // 7. Возвращаем результат для PostgreSQL.
  return {
    json: {
      id: source.id,
      telegram_token: source.telegram_token,
      telegram_attempts: attempts,

      permanent,

      delay_seconds: delaySeconds,

      safe_error: validStatus
        ? `TELEGRAM_HTTP_${status}`
        : "TELEGRAM_SEND_ERROR"
    },

    pairedItem: {
      item: index
    }
  };
});

